const initHomeParallax=()=>{
const hero=document.querySelector('.home-hero'),layers=[...document.querySelectorAll('.parallax-layer')];
if(!hero||!layers.length||!('IntersectionObserver'in window))return;
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
if(reduced.matches)return;
const maxOffsets=[8,32,64,96];
let active=false,frame=0,startY=0,height=0;
const measure=()=>{const rect=hero.getBoundingClientRect();startY=rect.top+window.scrollY;height=rect.height};
const reset=()=>layers.forEach(layer=>layer.style.setProperty('--parallax-offset','0px'));
const update=()=>{frame=0;if(!active)return;const progress=height?Math.max(0,Math.min(1,(window.scrollY-startY)/height)):0;layers.forEach((layer,index)=>{const offset=progress*(maxOffsets[index]??maxOffsets[maxOffsets.length-1]);layer.style.setProperty('--parallax-offset',offset.toFixed(2)+'px')})};
const onScroll=()=>{if(active&&!frame)frame=window.requestAnimationFrame(update)};
const stop=()=>{active=false;window.removeEventListener('scroll',onScroll);if(frame)window.cancelAnimationFrame(frame);frame=0;reset()};
const observer=new IntersectionObserver(entries=>{const visible=entries.some(entry=>entry.isIntersecting);if(visible&&!active&&!reduced.matches){active=true;measure();window.addEventListener('scroll',onScroll,{passive:true});onScroll()}else if(!visible&&active)stop()},{rootMargin:'40px 0px'});
observer.observe(hero);
window.addEventListener('resize',()=>{if(reduced.matches)stop();else if(active){measure();onScroll()}},{passive:true});
reduced.addEventListener('change',event=>{if(event.matches)stop()});
};
